Algoritmo Menu
  Definir codigo Como Entero;
  Leer codigo;
  Segun codigo Hacer
    1:
      Escribir "Jugo 3";
    2:
      Escribir "Sándwich 5";
    3:
      Escribir "Alfajor 2";
    4:
      Escribir "Agua 1";
    5:
      Escribir "Fruta 2";
    De Otro Modo:
      Escribir "No existe";
  FinSegun
FinAlgoritmo

Algoritmo Bisiesto
  Definir anio Como Entero;
  Leer anio;
  Si anio mod 400 = 0 Entonces
    Escribir "Es bisiesto";
  Sino
    Si anio mod 100 = 0 Entonces
      Escribir "No es bisiesto";
    Sino
      Si anio mod 4 = 0 Entonces
        Escribir "Es bisiesto";
      Sino
        Escribir "No es bisiesto";
      FinSi
    FinSi
  FinSi
FinAlgoritmo

Algoritmo Bisiesto
  Definir anio Como Entero;
  Leer anio;
  Si (anio mod 4 = 0 Y anio mod 100 <> 0) O anio mod 400 = 0 Entonces
    Escribir "Es bisiesto";
  Sino
    Escribir "No es bisiesto";
  FinSi
FinAlgoritmo

Algoritmo Cine
  Definir dia Como Entero;
  Definir edad Como Entero;
  Leer dia;
  Leer edad;
  Si dia = 4 Entonces
    Escribir "Paga 4";
  Sino
    Si edad < 12 Entonces
      Escribir "Paga 5";
    Sino
      Escribir "Paga 8";
    FinSi
  FinSi
FinAlgoritmo
